// Spread correct answers evenly over the five positions so the key cannot be guessed from a pattern.
// Questions with ordered options (numbers, years, reigns) keep their order; "ถูกทุกข้อ"/"ไม่มีข้อใดถูก" stays last.
const fixedLast=o=>o==='ถูกทุกข้อ'||o==='ไม่มีข้อใดถูก';
const ordered=q=>q.options.some(o=>/^\d|ค\.ศ\.|พ\.ศ\.|รัชกาลที่/.test(o));
function balance(questions,seed){return questions.map((q,i)=>{if(ordered(q))return q;const last=fixedLast(q.options[4]);if(last&&q.answer===4)return q;const target=(i*2+seed)%(last?4:5);if(target===q.answer)return q;const options=[...q.options];[options[target],options[q.answer]]=[options[q.answer],options[target]];return {...q,options,answer:target};});}
Object.values(prep).forEach((g,i)=>{g.questions=balance(g.questions,i);});
export const prepIds = Object.keys(prep);
